{%- endif %}
{%- if ui_t(ui_eq(v_value, 'no')) %}
  {%- set c_4 -%}
    {{ include('ui/lucide-icon/lucide-icon.html.twig', {'p': {'Name': 'minus', 'Size': 16}}, with_context = false) }}
